div.script:
(function(){
  const banner = document.getElementById('banner');
  const mc = document.getElementById('main-canvas');
  const fc = document.getElementById('fall-canvas');
  const bc = document.getElementById('branch-petal-canvas');
  let W, H;

  function resize(){
    W = banner.clientWidth; H = banner.clientHeight;
    mc.width=W; mc.height=H;
    fc.width=W; fc.height=H;
    bc.width=W; bc.height=H;
    drawScene();
  }

  const ctx = mc.getContext('2d');
  const pctx = fc.getContext('2d');
  const bctx = bc.getContext('2d');

  function sakuraFlower(cx, cy, r, rot, col1, col2, alpha){
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.translate(cx, cy);
    ctx.rotate(rot);
    for(let i=0;i<5;i++){
      ctx.save();
      ctx.rotate((Math.PI*2/5)*i + Math.PI/10);
      ctx.beginPath();
      ctx.moveTo(0,0);
      ctx.bezierCurveTo( r*0.6, r*0.1,  r*0.85, r*0.7,  r*0.35, r*1.1);
      ctx.bezierCurveTo( r*0.15,r*1.35, 0,      r*1.4,  0,      r*1.4);
      ctx.bezierCurveTo( 0,     r*1.4, -r*0.15, r*1.35,-r*0.35, r*1.1);
      ctx.bezierCurveTo(-r*0.85,r*0.7, -r*0.6,  r*0.1,  0,      0);
      const g = ctx.createLinearGradient(0,0,0,r*1.4);
      g.addColorStop(0, col1);
      g.addColorStop(1, col2);
      ctx.fillStyle = g;
      ctx.fill();
      ctx.beginPath();
      ctx.moveTo(0, r*1.0);
      ctx.lineTo(0, r*1.35);
      ctx.strokeStyle='rgba(160,50,100,0.3)';
      ctx.lineWidth=0.5;
      ctx.stroke();
      ctx.restore();
    }
    ctx.beginPath();
    ctx.arc(0,0,r*0.26,0,Math.PI*2);
    ctx.fillStyle='#ffe8f2';
    ctx.fill();
    for(let i=0;i<7;i++){
      const a=(Math.PI*2/7)*i;
      const len=r*0.52;
      ctx.beginPath();
      ctx.moveTo(Math.cos(a)*r*0.16,Math.sin(a)*r*0.16);
      ctx.lineTo(Math.cos(a)*len,Math.sin(a)*len);
      ctx.strokeStyle='rgba(255,160,210,0.55)';
      ctx.lineWidth=0.5;
      ctx.stroke();
      ctx.beginPath();
      ctx.arc(Math.cos(a)*len,Math.sin(a)*len,r*0.07,0,Math.PI*2);
      ctx.fillStyle='#ffb8d8';
      ctx.fill();
    }
    ctx.restore();
  }

  function silCluster(cx,cy,spread,count,col,alpha){
    ctx.save();
    ctx.globalAlpha=alpha;
    for(let i=0;i<count;i++){
      const ox=(Math.random()-0.5)*spread;
      const oy=(Math.random()-0.5)*spread*0.55;
      const r=5+Math.random()*11;
      for(let p=0;p<5;p++){
        ctx.beginPath();
        ctx.ellipse(cx+ox+Math.cos((Math.PI*2/5)*p)*r*0.75,
                    cy+oy+Math.sin((Math.PI*2/5)*p)*r*0.75,
                    r*0.65,r*0.88,(Math.PI*2/5)*p,0,Math.PI*2);
        ctx.fillStyle=col; ctx.fill();
      }
      ctx.beginPath();
      ctx.arc(cx+ox,cy+oy,r*0.32,0,Math.PI*2);
      ctx.fillStyle=col; ctx.fill();
    }
    ctx.restore();
  }

  function drawBranch(x1,y1,x2,y2,w){
    ctx.beginPath();
    ctx.moveTo(x1,y1);
    const mx=(x1+x2)/2+(y2-y1)*0.08;
    const my=(y1+y2)/2-(x2-x1)*0.08;
    ctx.quadraticCurveTo(mx,my,x2,y2);
    ctx.strokeStyle='#3d1020';
    ctx.lineWidth=w;
    ctx.lineCap='round';
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(x1,y1);
    ctx.quadraticCurveTo(mx,my,x2,y2);
    ctx.strokeStyle='rgba(110,35,55,0.35)';
    ctx.lineWidth=w*0.35;
    ctx.stroke();
  }

  function flowersBranch(x1,y1,x2,y2,count,sz,col1,col2,alpha){
    for(let i=0;i{
      const g=ctx.createRadialGradient(gx,gy,0,gx,gy,gr);
      g.addColorStop(0,gc); g.addColorStop(1,'rgba(13,8,24,0)');
      ctx.fillStyle=g; ctx.fillRect(0,0,W,H);
    });
    const s=W/900;
    const sil='#4a1840', sil2='#3d1260';
    silCluster(W*0.0,H*0.60,80*s,7,sil,0.55);
    silCluster(W*0.06,H*0.42,75*s,6,sil,0.48);
    silCluster(W*0.15,H*0.25,90*s,8,sil,0.52);
    silCluster(W*0.28,H*0.14,100*s,8,sil,0.44);
    silCluster(W*0.42,H*0.08,95*s,7,sil2,0.38);
    silCluster(W*0.58,H*0.06,90*s,6,sil2,0.33);
    silCluster(W*0.72,H*0.08,80*s,6,sil2,0.30);
    silCluster(W*0.85,H*0.12,75*s,5,sil2,0.26);
    silCluster(W*0.96,H*0.20,65*s,4,sil2,0.22);
    silCluster(W*1.0,H*0.35,70*s,5,sil2,0.20);
    silCluster(W*0.50,H*0.28,80*s,5,'#3a0e50',0.22);
    drawBranch(W*-0.02,H*-0.05,W*0.14,H*0.28,16*s);
    drawBranch(W*0.14,H*0.28,W*0.30,H*0.52,11*s);
    drawBranch(W*-0.02,H*-0.05,W*0.26,H*0.17,13*s);
    drawBranch(W*0.26,H*0.17,W*0.50,H*0.11,9*s);
    drawBranch(W*0.50,H*0.11,W*0.70,H*0.05,7*s);
    drawBranch(W*0.70,H*0.05,W*0.88,H*0.02,5*s);
    drawBranch(W*0.88,H*0.02,W*1.03,H*0.04,3.5*s);
    drawBranch(W*0.10,H*0.14,W*0.24,H*0.33,8*s);
    drawBranch(W*0.24,H*0.33,W*0.38,H*0.48,5.5*s);
    drawBranch(W*0.38,H*0.48,W*0.46,H*0.60,3.5*s);
    drawBranch(W*0.26,H*0.17,W*0.20,H*0.36,5.5*s);
    drawBranch(W*0.20,H*0.36,W*0.15,H*0.54,4*s);
    drawBranch(W*0.15,H*0.54,W*0.10,H*0.68,2.5*s);
    drawBranch(W*0.50,H*0.11,W*0.46,H*0.26,5*s);
    drawBranch(W*0.46,H*0.26,W*0.42,H*0.42,3.5*s);
    drawBranch(W*0.42,H*0.42,W*0.38,H*0.55,2*s);
    drawBranch(W*0.70,H*0.05,W*0.66,H*0.20,4.5*s);
    drawBranch(W*0.66,H*0.20,W*0.62,H*0.34,3*s);
    drawBranch(W*0.62,H*0.34,W*0.58,H*0.46,2*s);
    drawBranch(W*0.88,H*0.02,W*0.85,H*0.16,3*s);
    drawBranch(W*0.85,H*0.16,W*0.82,H*0.30,2*s);
    drawBranch(W*0.82,H*0.30,W*0.80,H*0.42,1.5*s);
    drawBranch(W*0.34,H*0.20,W*0.29,H*0.30,3*s);
    drawBranch(W*0.29,H*0.30,W*0.25,H*0.40,2*s);
    drawBranch(W*0.58,H*0.08,W*0.55,H*0.20,3*s);
    drawBranch(W*0.55,H*0.20,W*0.52,H*0.30,2*s);
    drawBranch(W*0.76,H*0.04,W*0.74,H*0.14,2.5*s);
    drawBranch(W*0.93,H*0.03,W*0.91,H*0.13,2*s);
    drawBranch(W*0.46,H*0.26,W*0.50,H*0.36,2*s);
    drawBranch(W*0.24,H*0.33,W*0.28,H*0.43,2*s);
    drawBranch(W*1.02,H*0.40,W*0.80,H*0.22,9*s);
    drawBranch(W*0.80,H*0.22,W*0.62,H*0.14,6*s);
    drawBranch(W*1.02,H*0.40,W*0.84,H*0.50,6*s);
    drawBranch(W*0.84,H*0.50,W*0.70,H*0.58,4*s);
    drawBranch(W*0.80,H*0.22,W*0.84,H*0.36,4*s);
    drawBranch(W*0.84,H*0.36,W*0.88,H*0.48,2.5*s);
    drawBranch(W*0.62,H*0.14,W*0.60,H*0.26,3.5*s);
    drawBranch(W*-0.01,H*0.85,W*0.12,H*0.62,8*s);
    drawBranch(W*0.12,H*0.62,W*0.22,H*0.45,5.5*s);
    drawBranch(W*0.22,H*0.45,W*0.30,H*0.32,4*s);
    drawBranch(W*0.12,H*0.62,W*0.06,H*0.50,4*s);
    drawBranch(W*0.06,H*0.50,W*0.02,H*0.40,2.5*s);
    drawBranch(W*0.22,H*0.45,W*0.18,H*0.35,3*s);
    const lc1='#ffeaf4',lc2='#f0a0c8',mc1='#f8d0e8',mc2='#c860a0',dc1='#e080b0',dc2='#903870';
    flowersBranch(W*-0.02,H*-0.05,W*0.26,H*0.17,10,10*s,lc1,lc2,0.93);
    flowersBranch(W*0.26,H*0.17,W*0.50,H*0.11,12,9*s,lc1,lc2,0.91);
    flowersBranch(W*0.50,H*0.11,W*0.70,H*0.05,10,8*s,mc1,mc2,0.87);
    flowersBranch(W*0.70,H*0.05,W*0.88,H*0.02,8,7*s,mc1,mc2,0.82);
    flowersBranch(W*0.88,H*0.02,W*1.03,H*0.04,6,6*s,dc1,dc2,0.72);
    flowersBranch(W*-0.02,H*-0.05,W*0.14,H*0.28,8,9*s,lc1,lc2,0.88);
    flowersBranch(W*0.14,H*0.28,W*0.30,H*0.52,6,7*s,mc1,mc2,0.78);
    flowersBranch(W*0.10,H*0.14,W*0.24,H*0.33,8,8*s,lc1,lc2,0.86);
    flowersBranch(W*0.24,H*0.33,W*0.38,H*0.48,7,7*s,mc1,mc2,0.80);
    flowersBranch(W*0.38,H*0.48,W*0.46,H*0.60,4,6*s,dc1,dc2,0.68);
    flowersBranch(W*0.26,H*0.17,W*0.20,H*0.36,7,7*s,mc1,mc2,0.82);
    flowersBranch(W*0.20,H*0.36,W*0.15,H*0.54,5,6*s,dc1,dc2,0.72);
    flowersBranch(W*0.15,H*0.54,W*0.10,H*0.68,3,5*s,dc1,dc2,0.60);
    flowersBranch(W*0.50,H*0.11,W*0.46,H*0.26,6,7*s,mc1,mc2,0.80);
    flowersBranch(W*0.46,H*0.26,W*0.42,H*0.42,5,6*s,dc1,dc2,0.72);
    flowersBranch(W*0.42,H*0.42,W*0.38,H*0.55,3,5*s,dc1,dc2,0.62);
    flowersBranch(W*0.70,H*0.05,W*0.66,H*0.20,6,7*s,mc1,mc2,0.78);
    flowersBranch(W*0.66,H*0.20,W*0.62,H*0.34,4,6*s,dc1,dc2,0.68);
    flowersBranch(W*0.62,H*0.34,W*0.58,H*0.46,3,5*s,dc1,dc2,0.58);
    flowersBranch(W*0.88,H*0.02,W*0.85,H*0.16,5,6*s,dc1,dc2,0.70);
    flowersBranch(W*0.85,H*0.16,W*0.82,H*0.30,4,5*s,dc1,dc2,0.62);
    flowersBranch(W*0.82,H*0.30,W*0.80,H*0.42,2,4*s,dc1,dc2,0.52);
    flowersBranch(W*0.34,H*0.20,W*0.29,H*0.30,4,6*s,mc1,mc2,0.76);
    flowersBranch(W*0.29,H*0.30,W*0.25,H*0.40,3,5*s,dc1,dc2,0.66);
    flowersBranch(W*0.58,H*0.08,W*0.55,H*0.20,4,6*s,mc1,mc2,0.72);
    flowersBranch(W*0.55,H*0.20,W*0.52,H*0.30,3,5*s,dc1,dc2,0.62);
    flowersBranch(W*0.76,H*0.04,W*0.74,H*0.14,3,5*s,dc1,dc2,0.65);
    flowersBranch(W*0.93,H*0.03,W*0.91,H*0.13,3,5*s,dc1,dc2,0.60);
    flowersBranch(W*0.46,H*0.26,W*0.50,H*0.36,3,5*s,dc1,dc2,0.62);
    flowersBranch(W*0.24,H*0.33,W*0.28,H*0.43,3,5*s,dc1,dc2,0.65);
    flowersBranch(W*1.02,H*0.40,W*0.80,H*0.22,7,8*s,mc1,mc2,0.80);
    flowersBranch(W*0.80,H*0.22,W*0.62,H*0.14,6,7*s,mc1,mc2,0.76);
    flowersBranch(W*1.02,H*0.40,W*0.84,H*0.50,5,7*s,dc1,dc2,0.68);
    flowersBranch(W*0.80,H*0.22,W*0.84,H*0.36,4,6*s,dc1,dc2,0.65);
    flowersBranch(W*0.62,H*0.14,W*0.60,H*0.26,3,5*s,dc1,dc2,0.62);
    flowersBranch(W*-0.01,H*0.85,W*0.12,H*0.62,5,7*s,mc1,mc2,0.78);
    flowersBranch(W*0.12,H*0.62,W*0.22,H*0.45,6,7*s,mc1,mc2,0.80);
    flowersBranch(W*0.22,H*0.45,W*0.30,H*0.32,5,7*s,lc1,lc2,0.82);
    flowersBranch(W*0.12,H*0.62,W*0.06,H*0.50,4,6*s,dc1,dc2,0.68);
    flowersBranch(W*0.22,H*0.45,W*0.18,H*0.35,3,6*s,mc1,mc2,0.72);
    for(let i=0;i<18;i++){
      const fx=W*(Math.random()*0.45);
      const fy=H*(Math.random()*0.55);
      const r=(4+Math.random()*6)*s;
      const bright=Math.random()<0.6;
      sakuraFlower(fx,fy,r,Math.random()*Math.PI*2,bright?lc1:mc1,bright?lc2:mc2,bright?0.72:0.52);
    }
    for(let i=0;i<10;i++){
      const fx=W*(0.55+Math.random()*0.48);
      const fy=H*(Math.random()*0.38);
      const r=(3+Math.random()*5)*s;
      sakuraFlower(fx,fy,r,Math.random()*Math.PI*2,mc1,mc2,0.55+Math.random()*0.2);
    }
    for(let i=0;i<18;i++){
      const px=W*(0.1+Math.random()*0.9);
      const py=H*(0.05+Math.random()*0.88);
      const pr=(1.8+Math.random()*3)*s;
      ctx.save();
      ctx.globalAlpha=0.18+Math.random()*0.28;
      ctx.translate(px,py);
      ctx.rotate(Math.random()*Math.PI*2);
      ctx.beginPath();
      ctx.moveTo(0,0);
      ctx.bezierCurveTo(pr*0.8,-pr*0.5,pr*0.9,-pr*2,0,-pr*2.2);
      ctx.bezierCurveTo(-pr*0.9,-pr*2,-pr*0.8,-pr*0.5,0,0);
      ctx.fillStyle=Math.random()<0.6?'#e090b8':'#f8c0dc';
      ctx.fill();
      ctx.restore();
    }
    const vg=ctx.createLinearGradient(0,H*0.5,0,H);
    vg.addColorStop(0,'rgba(13,8,24,0)');
    vg.addColorStop(1,'rgba(13,8,24,0.9)');
    ctx.fillStyle=vg; ctx.fillRect(0,0,W,H);
  }

  // falling petals
  const PCOLS=['#f0a0c8','#ffd8ec','#e878b0','#ffeaf4','#c86090','#f8c0dc','#ffc0e0','#e060a0'];
  function Petal(){
    this.reset=function(){
      this.x=Math.random()*W*1.15-W*0.08;
      this.y=-15-Math.random()*80;
      this.r=(1.6+Math.random()*3.4)*(W/900);
      this.vy=0.25+Math.random()*0.55;
      this.vx=(Math.random()-0.46)*0.75;
      this.angle=Math.random()*Math.PI*2;
      this.spin=(Math.random()-0.5)*0.042;
      this.sway=Math.random()*Math.PI*2;
      this.swayS=0.012+Math.random()*0.022;
      this.swayA=0.22+Math.random()*0.75;
      this.alpha=0.42+Math.random()*0.52;
      this.ay=0.38+Math.random()*0.38;
      this.col=PCOLS[Math.floor(Math.random()*PCOLS.length)];
    };
    this.reset();
    this.y=Math.random()*H;
  }
  const petals=Array.from({length:90},()=>new Petal());

  function animPetals(){
    pctx.clearRect(0,0,W,H);
    for(const p of petals){
      p.sway+=p.swayS;
      p.x+=p.vx+Math.sin(p.sway)*p.swayA;
      p.y+=p.vy;
      p.angle+=p.spin;
      if(p.y>H+18||p.x<-20||p.x>W+20) p.reset();
      pctx.save();
      pctx.globalAlpha=p.alpha;
      pctx.translate(p.x,p.y);
      pctx.rotate(p.angle);
      for(let i=0;i<5;i++){
        pctx.save();
        pctx.rotate((Math.PI*2/5)*i+Math.PI/10);
        pctx.beginPath();
        pctx.moveTo(0,0);
        pctx.bezierCurveTo(p.r*0.6,p.r*0.1,p.r*0.85,p.r*0.7,p.r*0.3,p.r*1.1);
        pctx.bezierCurveTo(p.r*0.12,p.r*1.3,0,p.r*1.35,0,p.r*1.35);
        pctx.bezierCurveTo(0,p.r*1.35,-p.r*0.12,p.r*1.3,-p.r*0.3,p.r*1.1);
        pctx.bezierCurveTo(-p.r*0.85,p.r*0.7,-p.r*0.6,p.r*0.1,0,0);
        pctx.fillStyle=p.col;
        pctx.fill();
        pctx.restore();
      }
      pctx.beginPath();
      pctx.arc(0,0,p.r*0.22,0,Math.PI*2);
      pctx.fillStyle='#ffe8f2';
      pctx.fill();
      pctx.restore();
    }
    requestAnimationFrame(animPetals);
  }

  // branch petals
  const BRANCH_POINTS = [
    [0.10, 0.14],[0.26, 0.17],[0.14, 0.28],[0.20, 0.36],
    [0.46, 0.26],[0.50, 0.11],[0.38, 0.48],[0.42, 0.42],
    [0.66, 0.20],[0.70, 0.05],[0.62, 0.34],[0.85, 0.16],
    [0.80, 0.22],[0.88, 0.02],[0.76, 0.04],[0.55, 0.20],
    [0.22, 0.45],[0.12, 0.62],[0.30, 0.32],[0.58, 0.08]
  ];

  function BranchPetal(){
    this.reset = function(){
      const bp = BRANCH_POINTS[Math.floor(Math.random()*BRANCH_POINTS.length)];
      this.x = bp[0]*W + (Math.random()-0.5)*18*(W/900);
      this.y = bp[1]*H + (Math.random()-0.5)*10*(W/900);
      this.r = (1.2+Math.random()*2.8)*(W/900);
      const ang = -Math.PI/2 + (Math.random()-0.5)*1.2;
      const spd = 0.3+Math.random()*0.9;
      this.vx = Math.cos(ang)*spd;
      this.vy = Math.sin(ang)*spd;
      this.grav = 0.012+Math.random()*0.018;
      this.angle = Math.random()*Math.PI*2;
      this.spin  = (Math.random()-0.5)*0.06;
      this.sway  = Math.random()*Math.PI*2;
      this.swayS = 0.016+Math.random()*0.02;
      this.swayA = 0.15+Math.random()*0.5;
      this.alpha = 0.55+Math.random()*0.45;
      this.col   = PCOLS[Math.floor(Math.random()*PCOLS.length)];
      this.life  = 0;
      this.maxLife = 180+Math.random()*220;
    };
    this.reset();
    this.life = Math.random()*this.maxLife;
    this.y += this.vy * this.life;
    this.x += this.vx * this.life;
    this.vy += this.grav * this.life;
  }

  const branchPetals = Array.from({length:60}, ()=>new BranchPetal());

  function drawSmallPetal(c, x, y, r, angle, col, alpha){
    c.save();
    c.globalAlpha = alpha;
    c.translate(x,y);
    c.rotate(angle);
    for(let i=0;i<5;i++){
      c.save();
      c.rotate((Math.PI*2/5)*i+Math.PI/10);
      c.beginPath();
      c.moveTo(0,0);
      c.bezierCurveTo(r*0.6,r*0.1,r*0.85,r*0.7,r*0.3,r*1.1);
      c.bezierCurveTo(r*0.12,r*1.3,0,r*1.35,0,r*1.35);
      c.bezierCurveTo(0,r*1.35,-r*0.12,r*1.3,-r*0.3,r*1.1);
      c.bezierCurveTo(-r*0.85,r*0.7,-r*0.6,r*0.1,0,0);
      c.fillStyle=col; c.fill();
      c.restore();
    }
    c.beginPath();
    c.arc(0,0,r*0.22,0,Math.PI*2);
    c.fillStyle='#ffe8f2'; c.fill();
    c.restore();
  }

  function animBranchPetals(){
    bctx.clearRect(0,0,W,H);
    for(const p of branchPetals){
      p.life++;
      if(p.life > p.maxLife){ p.reset(); continue; }
      const lifeRatio = p.life/p.maxLife;
      const fade = lifeRatio < 0.1 ? lifeRatio/0.1 : lifeRatio > 0.75 ? (1-lifeRatio)/0.25 : 1;
      p.sway += p.swayS;
      p.vy   += p.grav;
      p.x    += p.vx + Math.sin(p.sway)*p.swayA;
      p.y    += p.vy;
      p.angle += p.spin;
      if(p.y > H+20 || p.x < -20 || p.x > W+20){ p.reset(); continue; }
      drawSmallPetal(bctx, p.x, p.y, p.r, p.angle, p.col, p.alpha*fade);
    }
    requestAnimationFrame(animBranchPetals);
  }

  resize();
  animPetals();
  animBranchPetals();
  window.addEventListener('resize',()=>{ resize(); });
})();
